import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int res = new Solver().solveN(n);
        System.out.print(res);
        sc.close();
    }

    static class Solver {
        int MOD = 1000000007;

        int solveN(int n) {
            int maxDepth = 2 * n;
            int size = maxDepth + 1;
            int[][][] dp = new int[size * 2][size * 2][2];
            dp[0][0][0] = 1;
            for (int depth = 1; depth <= maxDepth; depth++) {
                for (int opened = depth & 1; opened <= depth; opened += 2) {
                    if (opened - 1 >= 0) {
                        dp[depth][opened][0] += dp[depth - 1][opened - 1][1];
                        dp[depth][opened][1] += dp[depth - 1][opened - 1][0];
                    }
                    if (opened + 1 < size) {
                        dp[depth][opened][0] += dp[depth - 1][opened + 1][1];
                        dp[depth][opened][1] += dp[depth - 1][opened + 1][0];
                    }
                    dp[depth][opened][0]++;
                    dp[depth][opened][0] %= MOD;
                    dp[depth][opened][1] %= MOD;
                }
            }
            return dp[maxDepth][0][1];
        }
    }
}
