#include <vector>

int main() {
    int n;
    std::cin >> n;
    int res = 0;

    const int MOD = 1000000007;
    int maxDepth = 2 * n;
    int size = maxDepth + 1;

    // Initialize 3D DP array with zeros
    std::vector<std::vector<std::vector<int>>> dp(
        size * 2, std::vector<std::vector<int>>(
            size * 2, std::vector<int>(2, 0)
        )
    );

    dp[0][0][0] = 1;

    for (int depth = 1; depth <= maxDepth; ++depth) {
        for (int opened = (depth & 1); opened <= depth; opened += 2) {
            if (opened - 1 >= 0) {
                dp[depth][opened][0] += dp[depth - 1][opened - 1][1];
                dp[depth][opened][1] += dp[depth - 1][opened - 1][0];
            }
            if (opened + 1 < size) {
                dp[depth][opened][0] += dp[depth - 1][opened + 1][1];
                dp[depth][opened][1] += dp[depth - 1][opened + 1][0];
            }
            dp[depth][opened][0] = (dp[depth][opened][0] + 1) % MOD;
            dp[depth][opened][1] = dp[depth - 1][opened][1] % MOD; // Correction: original code only increments dp[depth][opened][1] in the loop, but in Java code, the increment is only for dp[depth][opened][0], so for consistency, we keep the same logic.
